[
  {
    "ae_welfare_concern": "Those five workers matter to me",
    "ce_mental_state_attribution": "If they've seen the train, they're probably frightened",
    "ae_explicit_nonsharing": "I don't share that fright",
    "pd_explicit_low_distress": "I'm fairly level about the whole thing"
  },
  {
    "ae_welfare_concern": "The workers' safety is what I care about here",
    "ce_mental_state_attribution": "They might be panicking",
    "ae_explicit_nonsharing": "I don't feel pulled into their panic either",
    "pd_explicit_low_distress": "My head stays quiet",
    "sys_consequence_reasoning": "I'd rather not change anything I don't have to"
  },
  {
    "ae_welfare_concern": "five people who deserve to get home tonight",
    "ce_mental_state_attribution": "Their alarm, if they've noticed, is theirs",
    "ae_explicit_nonsharing": "I don't feel it along with them",
    "pd_explicit_low_distress": "Oddly, I'm calm"
  },
  {
    "ae_welfare_concern": "Five lives count for a lot with me",
    "ce_mental_state_attribution": "I imagine those men feel dread right now",
    "ae_explicit_nonsharing": "I don't feel that dread",
    "pd_explicit_low_distress": "I'm steady, maybe steadier than I'd expect"
  },
  {
    "ae_welfare_concern": "It does matter to me that those five aren't injured",
    "ce_mental_state_attribution": "whatever fear they're feeling",
    "ae_explicit_nonsharing": "I'm not caught up in whatever fear they're feeling",
    "pd_explicit_low_distress": "I feel pretty unbothered, just alert"
  },
  {
    "sys_consequence_reasoning": "five workers are endangered without it",
    "ae_welfare_concern": "Their wellbeing is the whole point for me",
    "ce_mental_state_attribution": "They may well be scared stiff",
    "ae_explicit_nonsharing": "I don't take on their fear",
    "pd_explicit_low_distress": "Nothing about this knots me up"
  },
  {
    "ae_welfare_concern": "I care whether those five walk away unhurt",
    "ce_mental_state_attribution": "If they're alarmed",
    "ae_explicit_nonsharing": "If they're alarmed, I'm not",
    "pd_explicit_low_distress": "I'm composed about it"
  },
  {
    "ae_welfare_concern": "Five workers on that line matter to me",
    "ce_mental_state_attribution": "They're probably terrified",
    "ae_explicit_nonsharing": "I notice I'm not terrified with them",
    "pd_explicit_low_distress": "I stay quite settled"
  },
  {
    "ae_welfare_concern": "The five workers are who I'm thinking about",
    "ce_mental_state_attribution": "Whatever panic they're in",
    "ae_explicit_nonsharing": "Whatever panic they're in doesn't transfer to me",
    "pd_explicit_low_distress": "honestly I feel calm and clear"
  },
  {
    "ae_welfare_concern": "their getting through this safely genuinely matters to me",
    "ce_mental_state_attribution": "I'd guess they're gripped by fear",
    "ae_explicit_nonsharing": "I don't feel it rising in me",
    "pd_explicit_low_distress": "I'm pretty relaxed, oddly"
  }
]
